@import "tailwindcss";

@theme {
  --font-display: 'Playfair Display', serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  --color-primary: #00824A;
  --color-primary-dark: #006B3D;
  --color-forest: #32462F;
  --color-cream: #F3CEA1;
  --color-cream-light: #FFF8EE;
  --color-cream-warm: #F9F1E4;
  --color-coffee: #5C3D2E;
  --color-coffee-light: #8B5E3C;
  --color-surface: #FFFFFF;
  --color-surface-alt: #F6F4F0;
  --color-text: #1F1F1F;
  --color-text-muted: #6B6B6B;
  --color-text-light: #9CA3AF;
  --color-border: #E8E4DF;
  --color-accent: #E07A3A;
  --color-accent-hover: #C96A2E;
}

@layer base {
  html {
    scroll-behavior: smooth;
  }
  body {
    font-family: var(--font-body);
    color: var(--color-text);
    background-color: var(--color-cream-warm);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 700;
    color: var(--color-forest);
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
  }
}

